      "IN-04-08": { title: "Historial", note: "La introducción, el calendario del mes con los días en que el instructor dio clase marcados y la leyenda, las clases agrupadas por día y el filtro de modalidad. Cuadro alto." },
      "IN-04-09": { title: "Historial — día seleccionado", note: "Un día seleccionado: solo sus clases y el acceso para limpiar con la fecha." },
