      "IN-06-02": { title: "Perfil", note: "El perfil con “Instructor” debajo del nombre, en la barra de pestañas del instructor. Las hojas y los estados son los mismos de ST-05-02 a ST-05-12. Cuadro alto." },
      "IN-06-03": { title: "Editar perfil", note: "El formulario con el nombre y el correo del instructor. Los estados son los mismos de ST-05-13 a ST-05-15." },
      "IN-06-04": { title: "WhatsApp", note: "La introducción y el formulario de WhatsApp. Los estados son los mismos de ST-05-16 a ST-05-18." },
      "IN-06-05": { title: "Reglas de la escuela", note: "Abiertas desde la fila “Reglas” del inicio (reglas de ejemplo). Los estados son los mismos de ST-05-19 a ST-05-22. Cuadro alto." },
      "IN-06-06": { title: "Avisos", note: "Una fila por cada tipo de aviso que el backend envía a un instructor, con el texto de la app, sin leer y leídas. Los estados son los mismos de ST-06-02 a ST-06-05. Cuadro alto." },
