      "AD-07-10": { title: "Reactivar — cargando", note: "Los esqueletos de las tarjetas (los mismos de las cuentas nuevas)." },
      "AD-07-11": { title: "Reactivar — error", note: "El estado de error con el botón de reintentar." },
      "AD-07-12": { title: "Cuentas quitadas", note: "La introducción con cuántas cuentas se pueden restaurar y las tarjetas con cuándo se quitó cada una, el día de la eliminación definitiva y restaurar. Marco alto." },
      "AD-07-13": { title: "Cuentas quitadas — vacío", note: "Ninguna cuenta quitada." },
      "AD-07-14": { title: "Cuentas quitadas — cargando", note: "Los esqueletos de las tarjetas." },
      "AD-07-15": { title: "Cuentas quitadas — error", note: "El estado de error con el botón de reintentar." },
      "AD-08-01": { title: "Quién — alumnos", note: "Los pasos en “Quién” (la clase aún por elegir), el modo de alumno de la escuela, la búsqueda, la lista de alumnos y el botón de elegir clase desactivado. Marco alto." },
