      "AD-08-05": { title: "Quién — clase de prueba", note: "El modo de clase de prueba: el nombre, el WhatsApp y la nota de que la clase no queda en el historial." },
      "AD-08-06": { title: "Clase", note: "Los pasos con el alumno elegido, el calendario con los días con clases marcados, las clases del día (la llena atenuada), el filtro de modalidad y el botón de inscribir. Marco alto." },
      "AD-08-07": { title: "Clase — día sin clases", note: "Un día sin clases por empezar." },
      "AD-08-08": { title: "Clase — cargando", note: "Los esqueletos de las tarjetas de clase." },
      "AD-08-09": { title: "Toast — inscrito", note: "La pantalla vuelve al inicio, con el toast de éxito." },
      "AD-09-01": { title: "Personas", note: "La pestaña de personas como la ve el admin, con él en la lista, en la barra de pestañas del admin. Los otros estados de la lista son los mismos de ST-04-02 a ST-04-08. Marco alto." },
      "AD-09-02": { title: "Sheet — alumno", note: "El sheet de un alumno con promover a instructor, promover a admin y quitar de la plataforma." },
      "AD-09-03": { title: "Sheet — instructor", note: "El sheet de un instructor con sus acciones de rol." },
