      "AD-10-08": { title: "Reglas de cancelación — error", note: "El estado de error con el botón de reintentar." },
      "AD-10-09": { title: "Reglas de la escuela", note: "La introducción, las reglas en el orden que ven los alumnos, con los botones de subir y bajar, y añadir regla. Marco alto." },
      "AD-10-10": { title: "Sheet de nueva regla", note: "El título, la explicación y la nota de que todos aceptan las reglas de nuevo." },
