      "AD-11-01": { title: "Mis clases", note: "Las clases que da el admin, como las ve el instructor (IN-04-01). Los otros estados son los mismos de IN-04-02 a IN-04-07. Marco alto." },
      "AD-11-02": { title: "Historial", note: "Las clases que dio el admin, como las ve el instructor (IN-04-08). Los otros estados son los mismos de IN-04-09 a IN-04-12. Marco alto." },
      "AD-11-03": { title: "Ocupación semanal", note: "La ocupación de la semana, como la ve el instructor (IN-05-01). Los otros estados son los mismos de IN-05-02 a IN-05-07. Marco alto." },
      "AD-11-04": { title: "Perfil", note: "El perfil con “Admin” debajo del nombre, en la barra de pestañas del admin. Los sheets y estados son los mismos de ST-05-02 a ST-05-12. Marco alto." },
      "AD-11-05": { title: "Editar perfil", note: "El formulario con el nombre y el correo del admin. Los estados son los mismos de ST-05-13 a ST-05-15." },
      "AD-11-06": { title: "WhatsApp", note: "La introducción y el formulario de WhatsApp. Los estados son los mismos de ST-05-16 a ST-05-18." },
      "AD-11-07": { title: "Reglas de la escuela (lectura)", note: "Abiertas desde el perfil (reglas de ejemplo). Los estados son los mismos de ST-05-19 a ST-05-22. Marco alto." },
      "AD-11-08": { title: "Avisos", note: "Una fila por cada tipo de aviso que el backend envía a un admin, con el texto de la app, sin leer y leídos. Los estados son los mismos de ST-06-02 a ST-06-05. Marco alto." },
